      "sourcePage": "https://commons.wikimedia.org/wiki/File:Human_karyotype_with_bands_and_sub-bands.png",
      "artist": "Mikael Häggström , M.D. Author info - Reusing images - Conflicts of interest: None Mikael Häggström , M.D. - The work integrates Public Domain source images by Was A Bee , Kelvin Ma and Michał Komorniczak - Also, a special acknowledgement to everyone involved in the Human Genome Project for generating the source data. editar",
