      "licenseUrl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en",
      "description": "Schematic and relatively language-neutral karyogram of a human. Even at low magnification, it gives an overview of the human genome , with numbered chromosome pairs, its main changes during the cell cycle (top center), and the mitochondrial genome to scale (at bottom left). High magnification ( of full size version ) more clearly depicts a scale to the left of each chromosome pair that shows the length in terms of million base pairs , and the scale to the right of each chromosome pair shows the designations of the bands and sub-bands . It shows darker and brighter regions as seen on G banding . Each row is vertically aligned at centromere level. The chromosomes are organized into the groups A to G in regard to size, position of the centromere and sometimes the presence of a chromosomal satellite. The chromosome copy numbers are those seen in G 0 and G 1 of the cell cycle , and at top center it also shows the state of the chromosome 3 pair in the metaphase of the cell cycle, after the synthesis of a copy of each chromosome. The karyogram shows: - 22 homologous autosomal chromosome pairs - Both the female (XX) and male (XY) versions of the two sex chromosomes (in green rectangle at bottom right). - The human mitochondrial genome to scale (at bottom left). For more information and context, see Wikipedia:Karyotype .",
